        "code": "def main(url: str):
	from urllib.parse import urlparse

	parsed = urlparse(url)
	path_parts = parsed.path.strip('/').split('/')

	if len(path_parts) < 2:
		raise ValueError("Invalid GitHub URL")

	owner = path_parts[0]
